import itertools

def langford_exists(n):
    # Try to find a Langford sequence for given n (2 copies of each 1..n)
    length = 2 * n
    # We can use backtracking or SAT. Let's use simple backtracking with recursion.
    # Represent sequence as list of None initially.
    seq = [None] * length

    def backtrack(v):
        if v > n:
            return True
        # Try to place the two copies of v
        for i in range(length - (v + 1)):
            if seq[i] is None and seq[i + v + 1] is None:
                seq[i] = v
                seq[i + v + 1] = v
                if backtrack(v + 1):
                    return True
                seq[i] = None
                seq[i + v + 1] = None
        return False

    if backtrack(1):
        return seq
    else:
        return None

for n in range(1, 9):
    sol = langford_exists(n)
    print(f"n={n}: {'SAT' if sol else 'UNSAT'}")
    if sol:
        print(sol)
